head.script:

	scwin.onpageload = function() {

	};

	scwin.onpageunload = function() {

	};

    scwin.onsubmenubtnclick = function() {
		localStorage.setItem("log1", 'onsubmenubtnclick');	
        console.log("onsubmenubtnclick");
    }

    scwin.onscrollleftbtnclick = function() {
		localStorage.setItem("log2", 'onscrollleftbtnclick');		
        console.log("onscrollleftbtnclick");
    }

    scwin.onscrollrightbtnclick = function() {
		localStorage.setItem("log3", 'onscrollrightbtnclick');		
        console.log("onscrollrightbtnclick");
    }

	function unitTest(){
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_btn_scrollLeft').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_btn_submenu').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wq_uuid_1_btn_scrollRight').click()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'onsubmenubtnclick'", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log2') == 'onscrollleftbtnclick'", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log3') == 'onscrollrightbtnclick'", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();        
	}
	unitTest();		
	localStorage.removeItem("log1");		
	localStorage.removeItem("log2");	
	localStorage.removeItem("log3");
